INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order, created_at) VALUES
(v_topic_id, 'Trial and error', '', 'Phương pháp thử và sai', 'Breakthroughs in human history are rarely single events, but rather a result of a gradual process of trial and error.', 'Test 2', 1, 101, NOW() + interval '7301 seconds'),
(v_topic_id, 'Cumulative nature', '', 'Tính chất tích lũy', 'Modern scientific progress builds upon previous discoveries, demonstrating an inherently strong cumulative nature.', 'Test 2', 1, 102, NOW() + interval '7302 seconds'),
(v_topic_id, 'Methodical investigation', '', 'Sự điều tra có phương pháp', 'The project aims to Methodical investigation for sustainable development.', 'Test 2', 1, 103, NOW() + interval '7303 seconds'),
(v_topic_id, 'Happy accident', '', 'Sự tình cờ may mắn', 'Many breakthrough inventions do not emerge from meticulous planning, but rather from a completely fortunate happy accident.', 'Test 2', 1, 104, NOW() + interval '7304 seconds'),
(v_topic_id, 'Law of Effect', '', 'Quy luật Tác động', 'Thorndike’s influential psychological principle explaining behavioral adaptation is widely known as the Law of Effect.', 'Test 2', 1, 105, NOW() + interval '7305 seconds'),
(v_topic_id, 'Natural selection', '', 'Sự chọn lọc tự nhiên', 'Biological organisms evolve over generations through random variations subject to the principles of natural selection.', 'Test 2', 1, 106, NOW() + interval '7306 seconds'),
(v_topic_id, 'Intelligent design', '', 'Thiết kế thông minh', 'Critics argue that relying on the concept of intelligent design ignores the mechanical and evolutionary steps behind creation.', 'Test 2', 1, 107, NOW() + interval '7307 seconds'),
(v_topic_id, 'Creative genius', '', 'Thiên tài sáng tạo', 'Society frequently attributes revolutionary breakthroughs to the sole brilliance of an exceptional creative genius.', 'Test 2', 1, 108, NOW() + interval '7308 seconds'),
(v_topic_id, 'Conventional wisdom', '', 'Quan niệm thông thường', 'Popular belief often clings to long-held assumptions, which are widely accepted as simple conventional wisdom.', 'Test 2', 1, 109, NOW() + interval '7309 seconds'),
(v_topic_id, 'Fanciful theory', '', 'Lý thuyết mang tính tưởng tượng', 'Nicholson proposed several unusual atomic models that were initially dismissed as merely a fanciful theory.', 'Test 2', 1, 110, NOW() + interval '7310 seconds'),
(v_topic_id, 'Speed advantage', '', 'Lợi thế về tốc độ', 'The novel jockey posture in horse racing unexpectedly provided competitors with a significant speed advantage.', 'Test 2', 1, 111, NOW() + interval '7311 seconds');
